import { VoltAgent } from '@voltagent/core';
import { LibSQLMemoryAdapter } from '@voltagent/libsql';

async function main() {
  const agent = new VoltAgent({
    name: 'MemoryAgent',
    instructions: 'You remember things.',
    memory: new LibSQLMemoryAdapter({
      url: 'file:memory.db'
    })
  });

  await agent.init();
  console.log('Agent created successfully.');

  process.exit(0);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

